import{_ as t,o as i,c as a,ae as o}from"./chunks/framework.Co1PSFSm.js";const p=JSON.parse('{"title":"Public Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"docs/public-view.md","filePath":"docs/public-view.md"}'),n={name:"docs/public-view.md"};function r(l,e,s,c,h,u){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="public-documentation" tabindex="-1">Public Documentation <a class="header-anchor" href="#public-documentation" aria-label="Permalink to &quot;Public Documentation&quot;">​</a></h1><p>The ultimate goal of the CM Transcription Equivalents tool is to publish your findings. The tool provides a built-in, static &quot;Public View&quot; that serves as an interactive documentation site for your notation system.</p><h2 id="generating-the-data" tabindex="-1">Generating the Data <a class="header-anchor" href="#generating-the-data" aria-label="Permalink to &quot;Generating the Data&quot;">​</a></h2><p>The public view relies on a single JSON file that contains all your hard work: definitions, global IDs, local overrides, line regions, and polygon coordinates.</p><ol><li>Navigate to the <strong>Settings</strong> or <strong>Export</strong> area of the application.</li><li>Look for the option to <strong>Export Public Data</strong> or generate <code>data.json</code>.</li><li>This process compiles your local database into a web-optimized format.</li></ol><h2 id="the-public-interface" tabindex="-1">The Public Interface <a class="header-anchor" href="#the-public-interface" aria-label="Permalink to &quot;The Public Interface&quot;">​</a></h2><p>The public-facing side of the application is completely separate from the editing tools. It is designed to be shared with other researchers or the general public.</p><h3 id="manuscript-directory" tabindex="-1">Manuscript Directory <a class="header-anchor" href="#manuscript-directory" aria-label="Permalink to &quot;Manuscript Directory&quot;">​</a></h3><p>A sortable index listing all the manuscripts you have annotated. Clicking a manuscript takes the user to its specific gallery.</p><h3 id="patterns-equivalents-index" tabindex="-1">Patterns &amp; Equivalents Index <a class="header-anchor" href="#patterns-equivalents-index" aria-label="Permalink to &quot;Patterns &amp; Equivalents Index&quot;">​</a></h3><p>A comprehensive summary table. It lists every Ref ID you have defined and shows exactly where it appears in the physical manuscripts (e.g., &quot;Found in St. Gallen 359, Folio 12r, Line 4&quot;).</p><h3 id="interactive-manuscript-gallery" tabindex="-1">Interactive Manuscript Gallery <a class="header-anchor" href="#interactive-manuscript-gallery" aria-label="Permalink to &quot;Interactive Manuscript Gallery&quot;">​</a></h3><p>This is the showcase feature.</p><ul><li>Users see a vertical scroll of the manuscript lines you defined.</li><li><strong>Hover Effects</strong>: Moving the mouse over the scan reveals interactive, colored labels highlighting the neumes you drew polygons around.</li><li><strong>Real-time Data</strong>: Hovering over a label displays a tooltip with the Ref ID, variant suffix, and the underlying transcription pattern string.</li></ul><h3 id="bidirectional-navigation" tabindex="-1">Bidirectional Navigation <a class="header-anchor" href="#bidirectional-navigation" aria-label="Permalink to &quot;Bidirectional Navigation&quot;">​</a></h3><p>The public view is highly interconnected:</p><div class="info custom-block"><p class="custom-block-title">💡 Suggestion for Future Documentation</p><p><em>[A screen recording demonstrating this bidirectional linking would be highly effective. Show a user clicking a row in the table, the page automatically scrolling down, and the corresponding shape pulsing on the manuscript scan.]</em></p></div><ul><li><strong>Table to Gallery</strong>: Clicking an occurrence listed in the Equivalents Table instantly scrolls the page to the visual gallery, bringing the specific manuscript line into view, and briefly animating the polygon to draw the user&#39;s eye to the exact spot on the page.</li><li><strong>Gallery to Table</strong>: Clicking an interactive label on the manuscript scan itself will scroll the user back up to the exact row in the Equivalents Table, allowing them to see how many other times that specific shape occurs.</li></ul><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>Because the public view is a static Vue application, it can be hosted anywhere for free. The primary intended deployment method is <strong>GitHub Pages</strong>.</p><ol><li>Run the production build command (<code>npm run build</code>).</li><li>This generates the necessary files in the <code>/docs</code> folder.</li><li>Push your repository to GitHub.</li><li>Enable GitHub Pages in your repository settings, pointing to the <code>/docs</code> folder on the <code>master</code> branch.</li><li>Your interactive notation gallery is now live on the internet!</li></ol>',21)])])}const g=t(n,[["render",r]]);export{p as __pageData,g as default};
